def run_parsing(self):
    """Executes the parsing alone."""
    self.parser.parse_file(self.master_file_path)

def run_generation(self, adapter_str=None):
    """"
    Runs the generation of all intents and writes them out to the output
    file(s) using the adapter `adapter` if one is provided.
    @pre: the parsing has been done.
    """
    if adapter_str is None:
        adapter = self.adapter
    else:
        adapter = adapter_factory.create_adapter(adapter_str)

    self.generator = Generator()
    synonyms = AST.get_or_create().get_entities_synonyms()

    if os.path.exists(self.output_dir_path):
        if self.force_overwriting or self._ask_confirmation():
            shutil.rmtree(self.output_dir_path)
        else:
            print_DBG("Aborting generation. Exiting without any change.")
            return

    train_examples = list(self.generator.generate_train())
    if train_examples:
        adapter.write(os.path.join(self.output_dir_path, "train"),
                      train_examples, synonyms)
    test_examples = list(self.generator.generate_test(train_examples))
    if test_examples:
        adapter.write(os.path.join(self.output_dir_path, "test"),
                      test_examples, synonyms)
    print_DBG("Generation over")

def wait_for_input(self):
    """
    Waits for the user to type a command, interprets it and executes it.
    """
    if self._dont_enter_interactive_mode:
        return
    while True:
        print(">>> ", end='')
        try:
            command_str = input()
        except EOFError:
            print("Exiting interactive mode")
            break
        if self.interpret_command(command_str):
            print("Exiting interactive mode")
            break

def execute_commands(self, commands):
    """
    Executes the list of commands `commands`
    as if they had been typed in by the user.
    Returns `True` if the interactive mode should be exited.
    """
    if commands is None:
        return False
    for cmd in commands:
        stop = self.interpret_command(cmd)
        if stop:
            return True
    return False

def get_command(command_str, quiet):
    """Factory method: creates the right command from the provided str."""
    try:  # For Python 3.x
        operation_name = command_str.split(maxsplit=1)[0].lower()
    except TypeError:  # For Python 2.7
        operation_name = command_str.split(None, 1)[0].lower()
    if operation_name == "exit":
        return exit_command.ExitCommand(command_str, quiet)
    if operation_name == "stats":
        return stats_command.StatsCommand(command_str, quiet)
    if operation_name == "parse":
        return parse_command.ParseCommand(command_str, quiet)
    if operation_name == "exist":
        return exist_command.ExistCommand(command_str, quiet)
    if operation_name == "rename":
        return rename_command.RenameCommand(command_str, quiet)
    if operation_name == "delete":
        return delete_command.DeleteCommand(command_str, quiet)
    if operation_name == "examples":
        return examples_command.ExamplesCommand(command_str, quiet)
    if operation_name == "hide":
        return hide_command.HideCommand(command_str, quiet)
    if operation_name == "unhide":
        return unhide_command.UnhideCommand(command_str, quiet)
    if operation_name == "execute":
        return execute_command.ExecuteCommand(command_str, quiet)
    if operation_name == "show":
        return show_command.ShowCommand(command_str, quiet)
    if operation_name == "rule":
        return rule_command.RuleCommand(command_str, quiet)
    if operation_name == "generate":
        return generate_command.GenerateCommand(command_str, quiet)
    if operation_name == "add-rule":
        return add_rule_command.AddRuleCommand(command_str, quiet)
    if operation_name == "declare":
        return declare_command.DeclareCommand(command_str, quiet)
    if operation_name == "set-modifier":
        return set_modifier_command.SetModifierCommand(command_str, quiet)
    if operation_name == "save":
        return save_command.SaveCommand(command_str, quiet)
    if not quiet:
        print("Unknown command: " + operation_name)
    return None

def get_template_post_modifiers(modifiers_repr):
    """
    Returns the string of post-modifiers as a string that would be found in
    a template file.
    """
    result = ""
    if modifiers_repr.randgen:
        result += RAND_GEN_SYM
        if modifiers_repr.randgen.name is not None:
            result += modifiers_repr.randgen.name
        if modifiers_repr.randgen.percentage != 50:
            result += \
                RAND_GEN_PERCENT_SYM + str(modifiers_repr.randgen.percentage) + '%'
    if modifiers_repr.variation_name is not None:
        result += VARIATION_SYM + modifiers_repr.variation_name
    if modifiers_repr.argument_name is not None:
        result += ARG_SYM + modifiers_repr.argument_name
    elif modifiers_repr.argument_value is not None:
        result += ARG_SYM
        if len(modifiers_repr.argument_value) == 1:
            for (name, value) in modifiers_repr.argument_value.items():
                result += value
        else:
            result += "ERROR"  # TODO do this when the new arg assignment lexing rule has been coded
    return result

def as_template_str(self):
