def execute(self):
    """
    Implements the command `generate` which generates all possible examples
    of a certain unit, formatted according to a certain adapter.
    """
    if not Facade.was_instantiated():
        self.print_wrapper.error_log(
            "Cannot generate anything. No file was parsed."
        )
        return
    facade = Facade.get_or_create()
    if len(self.command_tokens) == 1:
        facade.run_generation()
        return
    if len(self.command_tokens) == 2:
        try:
            facade.run_generation(self.command_tokens[1])
        except ValueError:
            self.print_wrapper.write(
                "Unknown adapter: '" + self.command_tokens[1] + "'"
            )
        return
    if len(self.command_tokens) < 4:
        self.print_wrapper.error_log(
            "Missing some arguments\nUsage: " + self.usage_str
        )
        return

    adapter_str = self.command_tokens[1]
    try:
        adapter = create_adapter(adapter_str)
    except ValueError:
        self.print_wrapper.error_log(
            "Unknown adapter '" + adapter_str + "'."
        )

    if len(self.command_tokens) == 5:
        try:
            self.nb_examples = int(self.command_tokens[-1])
        except ValueError:
            self.print_wrapper.error_log(
                "The number of examples to be generated is invalid: " + \
                "it must be an integer (no other characters allowed)."
            )
            return

    unit_type = \
        CommandStrategy.get_unit_type_from_str(self.command_tokens[2])
    if unit_type is None:
        self.print_wrapper.error_log(
            "Unknown unit type: '" + str(self.command_tokens[2]) + "'."
        )
        return

    unit_regex = self.get_regex_name(self.command_tokens[3])
    if unit_regex is None:
        print("no regex")
        try:
            [unit_name, variation_name] = \
                CommandStrategy.split_exact_unit_name(
                    self.command_tokens[3]
                )
        except SyntaxError:
            self.print_wrapper.error_log(
                "Unit identifier couldn't be interpreted. " + \
                "Did you mean to escape some hashtags '#'?"
            )
            return
        self._generate_unit(
            adapter, unit_type, unit_name, variation_name
        )
    else:
        count = 0
        for unit_name in self.next_matching_unit_name(
            unit_type, unit_regex
        ):
            self._generate_unit(adapter, unit_type, unit_name)
            count += 1
        if count == 0:
            self.print_wrapper.write("No " + unit_type.name + " matched.")
    self.finish_execution()

def create_adapter(adapter_name, base_filepath=None):
    """
    Instantiate an adapter and returns it given the name of the adapter as a str.
    Names are:
        - 'rasa': RasaAdapter
        - 'rasa-md' or 'rasamd': RasaMdAdapter
        - 'jsonl': JsonListAdapter
    """
    from chatette.adapters.jsonl import JsonListAdapter
    from chatette.adapters.rasa import RasaAdapter
    from chatette.adapters.rasa_md import RasaMdAdapter
    if adapter_name is None:
        return None
    adapter_name = adapter_name.lower()
    if adapter_name == 'rasa':
        return RasaAdapter(base_filepath)
    elif adapter_name in ('rasa-md', 'rasamd'):
        return RasaMdAdapter(base_filepath)
    elif adapter_name == 'jsonl':
        return JsonListAdapter(base_filepath)
    raise ValueError("Unknown adapter was selected.")

def cast_to_unicode(anything):
    """
    If executed with Python 2.7, cast any string that is in `anything`
    to unicode.
    If executed with Python 3, returns `anything`.
    `anything` can be a string, an array, a dict,...
    """
    if sys.version_info[0] == 3:
        return anything

    if isinstance(anything, str):
        return unicode(anything, "utf-8")
    if isinstance(anything, dict):
        cast_dict = dict()
        for key in anything:
            cast_key = cast_to_unicode(key)
            cast_value = cast_to_unicode(anything[key])
            cast_dict[cast_key] = cast_value
        return cast_dict
    if isinstance(anything, list):
        cast_list = []
        for e in anything:
            cast_list.append(cast_to_unicode(e))
        return cast_list
    return anything

def write(self, output_directory, examples, synonyms):
    super(JsonListAdapter, self).write(output_directory, examples, synonyms)

    processed_synonyms = self.__format_synonyms(synonyms)
    if processed_synonyms is not None:
        synonyms_file_path = os.path.join(output_directory, "synonyms.json")
        with io.open(synonyms_file_path, 'w') as output_file:
            output_file.write(
                json.dumps(
                    cast_to_unicode(processed_synonyms),
                    ensure_ascii=False, sort_keys=True, indent=2
                )
            )

def __format_synonyms(cls, synonyms):
    result = {
        key: values
        for (key, values) in synonyms.items()
        if len(values) > 1 or values[0] != key
    }
    if not result:
        return None
    return result

def sample_indulgent(array, nb_items):
    """
    Same as `random.sample` but doesn't raise an error if `nb_items`
    is larger than the length of `array`: in that case,
    simply returns (a copy of) the whole array.
    """
    if nb_items <= len(array):
        return sample(array, nb_items)
    return deepcopy(array)

def rchop(string, ending):
    """Removes a substring at the end of a string."""
    if string.endswith(ending):
        return string[:-len(ending)]
    return string

def remove_escapement(self):
    """Removes all the escapement from the text of this token."""
    processed_text = ""
    for i in range(len(self.text) - 1):
        if not (
            self.text[i] == ESCAPEMENT_SYM
            and self.text[i+1] in ESCAPABLE_CHARS
        ):
            processed_text += self.text[i]
    processed_text += self.text[-1]
    self.text = processed_text

def remove_comment_tokens(tokens):
    """
    Returns all the tokens except the ones that correspond to comments (and
    the preceding whitespaces if any).
    """
    if len(tokens) == 0:
        return tokens

    comment_index = None
    for (i, token) in enumerate(tokens):
        if token.type == TerminalType.comment:
            comment_index = i
            break

    if comment_index is None:
        return tokens
    if comment_index == 0:
        return []
    if tokens[comment_index - 1].type == TerminalType.whitespace:
        return tokens[:comment_index - 1]
    return tokens[:comment_index]

def remove_duplicates(dict_of_lists):
    """Removes duplicates from a dictionary containing lists."""
    return {key: list(set(value)) for (key, value) in dict_of_lists.items()}

def append_to_list_in_dict(dict_of_lists, key, value):
    """
    Given the dict of key->lists `dict_of_lists`, appends the value `value` to
    the list at key `key` if this list exist. Otherwise, creates a list
    containing `value` and puts it at key `key`.
    """
    if key not in dict_of_lists:
        dict_of_lists[key] = [value]
    else:
        dict_of_lists[key].append(value)

def extend_list_in_dict(dict_of_lists, key, values):
    """
    Given the dict of key->lists `dict_of_lists`, extends the list at key `key`
    with the values `values` if this list exist. Otherwise, puts the list
    `values` at key `key`.
    """
    if key not in dict_of_lists:
        dict_of_lists[key] = values
    else:
        dict_of_lists[key].extend(values)

def get_synonyms_dict(self):
    if self._synonyms is None:
        self._synonyms = dict()
        for rule in self._all_rules:
            texts = [ex.text for ex in rule.generate_all()]
            if rule.slot_value is None:
                for text in texts:
                    append_to_list_in_dict(self._synonyms, text, text)
            else:
                extend_list_in_dict(self._synonyms, rule.slot_value, texts)
    return self._synonyms

def min_if_exist(n1, n2):
    """
    Returns the minimum between two numbers, or the only defined number
    (in case the other is `None`) or `None` if none of the numbers are defined.
    """
    if n1 is None and n2 is None:
        return None
    elif n1 is None:
        return n2
    elif n2 is None:
        return n1
    return min(n1, n2)

def find_unescaped(text, str_to_find, start_index=0, end_index=None):
    """
    Finds the first occurrence of `str_to_find` in `text`
    and returns its first index.
    Returns `None` if nothing was found.
    The search is restricted to characters between `start_index` and
    `end_index` (if provided).
    `start_index` is included and `end_index` excluded.
    @pre: `str_to_find` should not contain escapements.
    """
    length = len(text)
    if len(str_to_find) == 0 or len(str_to_find) > length:
        return None
    if end_index is None:
        end_index = length

    current_index = start_index
    to_find_index = 0
    escaped = False
    while current_index < end_index:
        if escaped:
            escaped = False
        elif text[current_index] == ESCAPEMENT_SYM:
            escaped = True
        else:
            escaped = False
            if text[current_index] == str_to_find[to_find_index]:
                to_find_index += 1
            else:
                to_find_index = 0

        current_index += 1
        if to_find_index == len(str_to_find):
            break

    if to_find_index == len(str_to_find):
        return current_index - len(str_to_find)
    return None

def find_next_comment(text, start_index=0, end_index=None):
    """
    Finds the next comment in `text` starting from `start_index`
    until `end_index` (or the end of the text if it wasn't provided).
    Detects both new-style comments ('//') and old-style comments (';').
    @returns: the index of the beginning of the comment, or `None` if
              if no comment was found.
    """
    if end_index is None:
        end_index = len(text)

    comment_index = find_unescaped(text, COMMENT_SYM, start_index, end_index)
    old_comment_index = find_unescaped(
        text, OLD_COMMENT_SYM, start_index, end_index
    )
    return min_if_exist(comment_index, old_comment_index)

