def __repr__(self):
    if not self._present:
        return "No"
    result = "Yes"
    if self.name is not None:
        result += " '" + str(self.name) + "'"
    result += " ("
    if self.opposite:
        result += "opposite, "
    result += str(self.percentage) + "%)"
    return result

