def set_redirection_type(self, redirection_type):
    """
    Sets redirection type.
    @pre: `redirection_type` is of type `RedirectionType`.
    """
    if redirection_type == RedirectionType.append:
        self._file_mode = 'a+'
    elif redirection_type == RedirectionType.truncate:
        self._file_mode = 'w+'
    elif redirection_type == RedirectionType.quiet:
        self._file_mode = 'quiet'

def get_redirection(self):
    """
    Returns a 2-tuple containing the type and file path of the redirection.
    If this wrapper doesn't redirect to any file (or ignore prints),
    returns `None`.
    """
    if self._file_mode is None:
        return None
    if self._file_mode == 'quiet':
        return (RedirectionType.quiet, None)
    if self._file_mode == 'a+':
        return (RedirectionType.append, self.redirection_file_path)
    if self._file_mode == 'w+':
        return (RedirectionType.truncate, self.redirection_file_path)
    return None

def __get_file_name(self, batch, output_directory, single_file):
    # pylint: disable=bad-continuation
    if single_file:
        return \
            os.path.join(
                output_directory, "output." + self._get_file_extension()
            )
    return \
        os.path.join(
            output_directory, "output." + str(batch.index) + "." + \
            self._get_file_extension()
        )

def __get_file_name(self, batch, output_directory, single_file):
    if single_file:
        return \
            os.path.join(
                output_directory, "nlu." + self._get_file_extension()
            )
    raise ValueError(
        "Tried to generate several files with Rasa Markdown adapter."
    )

def get_current_file_information(self):
    if self._current_file is None:
        return (None, None)
    return (self._current_file.name, self._current_file.line_nb)

def write(self, text):
    if self.redirection_file_path is None and self._file_mode is None:
        print(text)
    elif self._file_mode == 'quiet':
        return
    else:
        if self.buffered_text is None:
            self.buffered_text = str(text)
        else:
            self.buffered_text += '\n' + str(text)

def error_log(self, text):
    processed_text = ''.join(['\t' + line + '\n'
                              for line in text.split('\n')])
    self.write("[ERROR]"+processed_text[:-1])

def execute_on_unit(self, unit_type, unit_name, variation_name=None):
    if self.nb_examples is None:  # Caching the parsed number
        self.nb_examples = -1  # All examples should be generated
        if len(self.command_tokens) > 3:
            try:
                self.nb_examples = int(self.command_tokens[3])
            except ValueError:
                self.print_wrapper.error_log(
                    "The number of examples to be generated is invalid: " + \
                    "it must be an integer (no other characters allowed)."
                )
                return
    try:
        definition = \
            AST.get_or_create()[unit_type][unit_name]
    except KeyError:
        self.print_wrapper.write(
            unit_type.name.capitalize() + " '" + unit_name + \
            "' is not defined."
        )
        return
    if self.nb_examples != -1:
        examples = definition.generate_nb_possibilities(
            self.nb_examples, variation_name=variation_name
        )
    else:
        examples = definition.generate_all(variation_name=variation_name)
    self.print_wrapper.write(
        "Examples for " + unit_type.name + " '" + unit_name + "':"
    )
    for ex in examples:
        self.print_wrapper.write(ex)
    self.print_wrapper.write("")

def execute_on_unit(self, unit_type, unit_name, variation_name=None):
    try:
        unit = AST.get_or_create()[unit_type][unit_name]
        if variation_name is None:
            self.stored_units[unit_type.name][unit_name] = unit
            self._units_to_delete.append((unit_type, unit_name))
            self.print_wrapper.write(
                unit_type.name.capitalize() + " '" + unit_name + \
                "' was successfully hidden."
            )
        else:
            if variation_name not in unit._variation_rules:
                self.print_wrapper.error_log(
                    "Couldn't find variation '" + variation_name + \
                    "' in " + unit_type.name + " '" + unit_name + "'."
                )
                return
            self._var_to_delete.append((unit_type, unit_name, variation_name))
            rules = unit._variation_rules[variation_name]
            if unit_name not in self.stored_variations[unit_type.name]:
                self.stored_variations[unit_type.name][unit_name] = \
                    {variation_name: rules}
            else:
                self.stored_variations[unit_type.name][unit_name][variation_name] = \
                    rules
            self.print_wrapper.write(
                "Variation '" + variation_name + "' of " + \
                unit_type.name + " '" + unit_name + \
                "' was successfully hidden."
            )
    except KeyError:
        self.print_wrapper.write(
            unit_type.name.capitalize() + " '" + unit_name + \
            "' was not defined."
        )

def close_all_files(self):
    """Closes all the opened files."""
    for f in self._opened_files:
        if not f.closed:
            f.close()
    if self._current_file is not None and not self._current_file.closed:
        self._current_file.close()

def _close_current_file(self):
    """
    Closes current file and
    continues reading the file previously being read (if any).
    """
    if self._current_file is not None:
        self._current_file.close()
    if len(self._opened_files) > 0:
        self._current_file = self._opened_files.pop()
    else:
        self._current_file = None

def __exit__(self, exc_type, exc_val, exc_tb):
    self.f.close()
    self.close()

