def as_dict(self):
    result = {"text": self.text, "entities": []}
    if self._slot_value is not None:
        result["slot-value"] = self._slot_value
    for entity in self.entities:
        result["entities"].append(entity.as_dict())
    return result

def _generate_random_strategy(self, variation_name=None):
    generated_example = \
        super(SlotDefinition, self)._generate_random_strategy(
            variation_name=variation_name
        )

    slot_value = generated_example._slot_value
    if slot_value is None:
        slot_value = generated_example.text
    generated_example.entities.append(
        Entity(self._name, len(generated_example.text), slot_value)
    )
    generated_example._slot_value = None

    return generated_example

def _generate_all_strategy(self, variation_name=None):
    generated_examples = \
        super(SlotDefinition, self)._generate_all_strategy(
            variation_name=variation_name
        )

    for ex in generated_examples:
        slot_value = ex._slot_value
        if slot_value is None:
            slot_value = ex.text
        ex.entities.append(
            Entity(self._name, len(ex.text), slot_value)
        )
        ex._slot_value = None

    return generated_examples

def finish_execution(self):
    for (unit_type, unit_name, variation_name) in self._units_to_delete:
        try:
            AST.get_or_create().delete_unit(
                unit_type, unit_name, variation_name
            )
            self.print_wrapper.write(
                unit_type.name.capitalize() + " '" + unit_name + \
                "' was successfully deleted."
            )
        except KeyError:
            self.print_wrapper.write(
                unit_type.name.capitalize() + " '" + unit_name + \
                "' was not defined."
            )
    self._units_to_delete = []

def finish_execution(self):
    for (unit_type, unit_name) in self._units_to_delete:
        AST.get_or_create().delete_unit(unit_type, unit_name)
    self._units_to_delete = []

    for (unit_type, unit_name, variation_name) in self._var_to_delete:
        AST.get_or_create().delete_unit(
            unit_type, unit_name, variation_name
        )
    self._var_to_delete = []

def modify_example(example):
    """
    Modifies the generated example `example` by applying
    the case generation modifier.
    Returns the modified example.
    """
    if random() < 0.5:
        return with_leading_upper(example)
    return with_leading_lower(example)

def may_change_leading_case(text):
    """
    Checks whether the string `text` can
    change the letter case of its leading letter.
    """
    for c in text:
        if c.isalpha():
            return True
        if c.isspace():
            continue
        return False
    return False

def extract_identifier(text, start_index=0):
    """
    Returns the part of `text` that starts at `start_index` and
    correponds to an identifier, key, value, argument name, randgen name,...
    Returns an empty string if no identifier was found.
    Returns `None` if `start_index` points to the end of the string.
    @raises: `ValueError` if `start_index` points to further than the end of
             `text`.
    """
    length = len(text)
    if start_index == length:
        return None
    elif start_index > length:
        raise ValueError("Tried to extract an identifier from outside a string.")

    i = start_index
    escaped = False
    while i < length:
        if escaped:
            escaped = False
            i += 1
            continue
        if text[i] == ESCAPEMENT_SYM:
            escaped = True
        elif (
            is_special_identifier_char(text[i]) \
            or text.startswith(COMMENT_SYM, i)
        ):
            break
        i += 1
    if i == start_index:
        return ""
    return text[start_index:i].rstrip()

def find_matching_choice_end(tokens, start_index):
    """
    Returns the index of the choice end that matches the choice start at
    index `start_index`.
    Returns `None` if there is no matching choice end.
    @raises: - `ValueError` if there is no choice starting at `start_index`.
             - `ValueError` if arguments are inconsistent.
    """
    if tokens[start_index].type != TerminalType.choice_start:
        raise ValueError(
            "Tried to get the matching choice end of something else than a " + \
            "choice start."
        )

    nb_starts_to_match = 0
    i = start_index + 1
    while i < len(tokens):
        token = tokens[i]
        if token.type == TerminalType.choice_start:
            nb_starts_to_match += 1
        elif token.type == TerminalType.choice_end:
            if nb_starts_to_match > 0:
                nb_starts_to_match -= 1
            else:
                return i
        i += 1
    return None

def find_index_last_choice_content(tokens, start_index):
    """
    Returns the index of the last token that makes up the internal rules
    of the choice starting at index `start_index`. In other words,
    the returned index points to the last token before the end of the choice
    or its random generation markers.
    Returns `None` if the choice is incorrectly closed.
    @raises: - `ValueError` if there isno choice starting at `start_index`.
    """
    end_choice_index = find_matching_choice_end(tokens, start_index)
    i = end_choice_index - 1
    if i > 0 and tokens[i].type == TerminalType.percentgen:
        i -= 1
    if i > 0 and tokens[i].type == TerminalType.percentgen_marker:
        i -= 1
    if i > 0 and tokens[i].type == TerminalType.randgen_name:
        i -= 1
    if i > 0 and tokens[i].type == TerminalType.opposite_randgen_marker:
        i -= 1
    if i > 0 and tokens[i].type == TerminalType.randgen_marker:
        i -= 1
    return i

def merge_randgen_mappings(example1, example2):
    """
    Returns the random generation mapping that corresponds to the union
    of that of both examples `example1` and `example2`.
    @pre: both mappings can be merged together.
    """
    mapping1 = getattr(example1, RANDGEN_MAPPING_KEY, None)
    mapping2 = getattr(example2, RANDGEN_MAPPING_KEY, None)
    if mapping1 is None:
        return deepcopy(mapping2)
    if mapping2 is None:
        return deepcopy(mapping1)

    result = deepcopy(mapping1)
    for randgen_name in mapping2:
        if randgen_name not in result:
            result[randgen_name] = deepcopy(mapping2[randgen_name])
    return result

def sort_by_texts(example_list):
    """
    Returns a sorted list of examples (with key == text).
    @pre: - `example_list` contains no duplicates.
    """
    return sorted(example_list, key=lambda ex: ex.text)

def extract_annotation_tokens(tokens):
    """
    Given the list of tokens `tokens`,
    returns a list of tokens that correspond to an annotation.
    Returns `None` if there was no annotation in `tokens`.
    """
    if len(tokens) < 2:
        return None

    start_index = None
    end_index = None
    for (i, token) in enumerate(tokens):
        if token.type == TerminalType.annotation_start:
            start_index = i
        if token.type == TerminalType.annotation_end:
            end_index = i
            break

    if start_index is None:
        return None
    if end_index is None:
        return tokens[start_index:]
    return tokens[start_index:end_index + 1]

def short_description(self):
    """
    Returns a short description (as a `str`) that can be displayed to the
    user.
    """
    at_least_one_modifier = False
    desc = ""
    if self.casegen:
        desc += "- case generation\n"
        at_least_one_modifier = True
    if self.randgen:
        desc += "- random generation"
        if self.randgen.name is not None:
            desc += ": " + self.randgen.name
        if self.randgen.opposite:
            desc += " [opposite]"
        desc += " (" + str(self.randgen.percentage) + "%)\n"
        at_least_one_modifier = True
    if self.argument_name is not None:
        desc += "- argument name: " + self.argument_name + "\n"
        at_least_one_modifier = True
    if self.argument_value is not None:
        desc += "- argument value: " + self.argument_value + "\n"
        at_least_one_modifier = True

    if not at_least_one_modifier:
        desc = "No modifiers\n"
    else:
        desc = "Modifiers:\n" + desc
    return desc

def _compute_nb_possibilities(self):
    """Returns the number of possible examples this item can generate."""
    raise NotImplementedError()

def get_max_cache_size(self):
    """
    Returns the maximum number of examples
    that should be cached for this item.
    """
    if self._max_nb_cached_ex is None:
        self.configure_max_cache_level(
            Configuration.get_or_create().caching_level
        )
    return self._max_nb_cached_ex

def generate_random(self, **kwargs):
    """
    Returns an example generated at random.
    Can use the cached examples in some cases (better performance).
    """
    # use cache with probability `len(cached)/nb_possibilities`
    if (
        len(self._cached_examples) > 0
        and uniform(0, 1) <= \
        float(len(self._cached_examples)) / float(self.get_max_nb_possibilities())
    ):
        return choice(deepcopy(self._cached_examples))
    example = self._generate_random_strategy()
    if self._leading_space:
        example.prepend(' ')
    return example

def generate_all(self):
    """
    Returns the list of all examples this item can generate.
    Can use the cached examples in some cases (better performance).
    Also sets up the cache if needed and fixes the count of possibilities.
    """
    if len(self._cached_examples) == self.get_max_nb_possibilities():
        return deepcopy(self._cached_examples)

    all_examples = self._generate_all_strategy()
    if self._leading_space:
        for ex in all_examples:
            ex.prepend(' ')
    if len(self._cached_examples) == 0 and self.get_max_cache_size() > 0:
        # TODO don't cache it all in all cases
        self._cached_examples = deepcopy(all_examples)
        self._total_nb_possibilities = len(all_examples)
    return all_examples

def generate_nb_possibilities(self, nb_possibilities, **kwargs):
    """
    Returns a list containing `nb_possibilities` examples,
    chosen at random in the set of all possible examples.
    Can use the cached examples in some cases (better performances).
    `kwargs` can contain `variation_name`.
    @pre: `nb_possibilities` >= 2 (otherwise call `generate_random`)
    """
    max_nb_possibilities = self.get_max_nb_possibilities(**kwargs)
    if nb_possibilities > max_nb_possibilities:
        nb_possibilities = max_nb_possibilities

    if len(self._cached_examples) >= max_nb_possibilities:
        return sample(self._cached_examples, nb_possibilities)
    if nb_possibilities < float(max_nb_possibilities) / 5.0:  # QUESTION: is 5 a good idea?
        return self._generate_n_strategy(nb_possibilities, **kwargs)
    return sample_indulgent(self.generate_all(**kwargs), nb_possibilities)

def generate_all(self, **kwargs):
    """Overriding."""
    if len(self._cached_examples) < self.get_max_nb_possibilities():
        basic_examples = self._generate_all_strategy(**kwargs)
        if self._leading_space:
            for ex in basic_examples:
                ex.prepend(' ')
        all_examples = self._apply_modifiers_to_all(basic_examples)
        if self.get_max_cache_size() > 0:
            self._cached_examples = deepcopy(all_examples)
        return all_examples
    return deepcopy(self._cached_examples)

def _generate_random_strategy(self):
    if self._leading_space:
        return Example(' ' + self._name)
    return Example(self._name)

def _choose_rule(self):
    """
    Returns a rule at random from the list of rules for this definition.
    Returns `None` if there are no rules.
    """
    if len(self._rules) == 0:
        return None
    return choice(self._rules)

def _generate_random_strategy(self):
    rule = self._choose_rule()
    if rule is None:
        raise SyntaxError(
            self.full_name.capitalize() + " does not have any rule to " + \
            "generate."
        )

    return rule.generate_random()

def _choose_rule(self, variation_name=None):
    """
    Returns a rule at random from the list of rules for this definition.
    Returns `None` if there are no rules.
    If `variation_name` is not `None`, the rule chosen should come
    from the corresponding variation (if it exists).
    """
    if variation_name is None:
        if len(self._all_rules) == 0:
            return None
        return choice(self._all_rules)
    else:
        if (
            variation_name not in self._variation_rules
            or len(self._variation_rules[variation_name]) == 0
        ):
            return None
        return choice(self._variation_rules[variation_name])

def _generate_random_strategy(self, variation_name=None):
    rule = self._choose_rule(variation_name)
    if rule is None:
        if variation_name is None:
            raise SyntaxError(
                self.full_name.capitalize() + " does not have any rule to " + \
                "generate."
            )
        else:
            raise SyntaxError(
                self.full_name.capitalize() + " does not have any rule " + \
                "associated to variation '" + str(variation_name) + "'."
            )

    example = rule.generate_random()
    example.remove_leading_space()
    if self.unit_type == UnitType.slot:
        example._slot_value = rule.slot_value
        if (
            example._slot_value is not None
            and example._slot_value.strip() == SLOT_VAL_FIRST_RULE
        ):
            if len(rule._contents) == 0:
                raise SyntaxError(
                    "The slot value given for one of the rules of " + \
                    self.full_name + " references the first token of " + \
                    "an empty rule."
                )
            example._slot_value = rule._contents[0]._name
    return example

def _get_relevant_dict(self, unit_type):
    """Returns the dict that stores units of type `unit_type`."""
    if unit_type == UnitType.alias:
        return self._alias_definitions
    elif unit_type == UnitType.slot:
        return self._slot_definitions
    elif unit_type == UnitType.intent:
        return self._intent_definitions
    else:
        raise TypeError(
            "Tried to get a definition with wrong type " + \
            "(expected alias, slot or intent)"
        )

def __getitem__(self, unit_type):
    """
    Returns the dictionary requested.
    `unit_type` can be either a str ("alias", "slot" or "intent")
    or a `UnitType`.
    @raises: - `KeyError` if `unit_type` is an invalid str.
             - `ValueError` if `unit_type´ is neither a str or a `UnitType`.
    """
    if isinstance(unit_type, str):
        if unit_type == UnitType.alias.value:
            unit_type = UnitType.alias
        elif unit_type == UnitType.slot.value:
            unit_type = UnitType.slot
        elif unit_type == UnitType.intent.value:
            unit_type = UnitType.intent
        else:
            raise KeyError(
                "Invalid key for the AST: '" + unit_type + "'."
            )
    elif not isinstance(unit_type, UnitType):
        raise TypeError(
            "Invalid type of key: " + unit_type.__class__.__name__ + "."
        )
    return self._get_relevant_dict(unit_type)

def add_slot(self, slot):
    """
    Adds the slot definition `slot` in the relevant dict.
    @raises: `ValueError` if the slot was already defined.
    """
    self._add_unit(UnitType.slot, slot)

def add_intent(self, intent):
    """
    Adds the intent definition `intent` in the relevant dict.
    @raises: `ValueError` if the intent was already defined.
    """
    self._add_unit(UnitType.intent, intent)

def add_unit(self, unit, unit_type=None):
    """
    Adds the unit definition `unit` in the relevant dict.
    If `unit_type` is `None`, detects the type of the definition
    by itself.
    @raises: - `TypeError` if the unit type is of an invalid type.
             - `ValueError` if the unit was already declared.
    """
    if unit_type is None:
        if isinstance(unit, AliasDefinition):
            unit_type = UnitType.alias
        elif isinstance(unit, SlotDefinition):
            unit_type = UnitType.slot
        elif isinstance(unit, IntentDefinition):
            unit_type = UnitType.intent
        else:
            raise TypeError(  # Should never happen
                "Tried to add something else than a unit definition " + \
                "to the AST."
            )
    self._add_unit(unit_type, unit)

def print_DBG(self):
    print("Aliases (" + str(len(self._alias_definitions)) + "):")
    for alias_name in self._alias_definitions:
        self._alias_definitions[alias_name].print_DBG()
    print("Slots (" + str(len(self._slot_definitions)) + "):")
    for slot_name in self._slot_definitions:
        self._slot_definitions[slot_name].print_DBG()
    print("Intents (" + str(len(self._intent_definitions)) + "):")
    for intent_name in self._intent_definitions:
        self._intent_definitions[intent_name].print_DBG()
    print()

def write(self, output_directory, examples, synonyms):
    """
    Creates files in `output/output_directory` and
    writes batches of the examples `examples` and synonyms `synonyms`
    into them.
    """
    if self._batch_size is not None:
        single_file_output = (len(examples) <= self._batch_size)
    else:
        single_file_output = True

    if not os.path.exists(output_directory):
        os.makedirs(output_directory)

    for batch in self.__generate_batch(examples, synonyms, self._batch_size):
        output_file_path = \
            self.__get_file_name(
                batch, output_directory, single_file_output
            )
        with io.open(output_file_path, 'w') as output_file:
            self._write_batch(output_file, batch)

def __init__(self, name, leading_space):
    super(Word, self).__init__(name, leading_space)
    self.word = name

def __init__(self, terminal_type, token_text):
    self.type = terminal_type
    if len(token_text) == 0 and (self.type != TerminalType.ignore):
        raise ValueError("Tried to create a lexed item of 0 characters.")
    self.text = token_text

def _compute_full_name(self):
    return "reference to " + self._unit_type.value + " '" + \
        self._name + "'"

def _compute_nb_possibilities(self):
    acc = 0
    for rule in self._rules:
        acc += rule.get_max_nb_possibilities()
    return acc

def _compute_nb_possibilities(self, variation_name=None):
    if variation_name is None:
        relevant_rules = self._all_rules
    elif variation_name in self._variation_rules:
        relevant_rules = self._variation_rules[variation_name]
    else:
        raise SyntaxError(
            "Referenced variation '" + str(variation_name) + "' for " + \
            self.full_name + ", but this variation has no rules " + \
            "associated to it."
        )

    acc = 0
    for rule in relevant_rules:
        acc += rule.get_max_nb_possibilities()
    return acc

def _generate_all_strategy(self):
    if self._leading_space:
        return [Example(' ' + self._name)]
    return [Example(self._name)]

def _generate_n_strategy(self, n=None):
    if self._leading_space:
        return [Example(' ' + self._name)]
    return [Example(self._name)]

def __init__(self, text=None, entities=None):
    if entities is None:
        entities = []
    if text is None:
        text = ""

    self.text = text
    self.entities = entities
    self._slot_value = None  # HACK used by slot to prevent code duplication

def __hash__(self):
    entities_hash = 0
    for entity in self.entities:
        entities_hash += hash(entity)
    return hash(self.text) * 10000 + entities_hash  # QUESTION not sure this a very good hash

def __hash__(self):
    return \
        hash(self.slot_name +"@" + str(self._start_index) + ":" + str(self.value))

def __eq__(self, other):
    if isinstance(other, Example) and not isinstance(other, IntentExample):
        raise TypeError("Tried to compare an Example and an IntentExample")
    return super(IntentExample, self).__eq__(other)

def remove_leading_space(self):
    """Removes the leading space of `self.text` if there is one."""
    if len(self.text) > 0 and self.text[0].isspace():
        self.text = self.text[1:]
        for entity in self.entities:
            entity._remove_leading_space()

def _remove_leading_space(self):
    """
    Adapts the start index and length if needed, after a leading space was
    removed from the example text.
    @returns: `True` if the entity still makes sense.
    """
    if self._start_index == 0:
        self._len -= 1
        if self._len <= 0:
            return False
    else:
        self._start_index -= 1
    return True

def _example_to_intent_example(self, example):
    """
    Turns the example `example` (of type `Example`) into an instance of
    `IntentExample`.
    """
    return IntentExample.from_example(example, self._name)

def _generate_random_strategy(self, variation_name=None):
    example = \
        super(IntentDefinition, self) \
            ._generate_random_strategy(variation_name=variation_name)
    return self._example_to_intent_example(example)

def __hash__(self):
    example_hash = super(IntentExample, self).__hash__()
    return hash(self.intent_name) * 1000000000 + example_hash  # QUESTION not sure this a very good hash

def as_dict(self):
    return {
        "slot-name": self.slot_name,
        "value": self.value,
        "start-index": self._start_index,
        "end-index": self._start_index + self._len
    }

def __init__(self, base_filepath=None, batch_size=10000):# -> None:
    super(RasaAdapter, self).__init__(base_filepath, batch_size)
    self._base_file_contents = None

def extend_no_dup(example_list, new_examples):
    """
    Adds each example in `new_examples`
    iff it has no duplicate in `example_list`
    @pre: - `example_list` must be a sorted list (with key == text).
          - `example_list` does not contain duplicates.
          - `new_examples` must be a sorted list (with key == text).
          - `new_examples` does not contain duplicates.
    @post: the returned list is sorted.
    """
    if len(new_examples) == 0:
        return example_list
    if len(example_list) == 0:
        return new_examples
    # TODO there might be a more optimized way to do that
    for ex in new_examples:
        example_list = add_example_no_dup(example_list, ex)
    return example_list

def generate_random(self, **kwargs):
    """
    Overriding.
    `kwargs` can contain the random name mapping `randgen_mapping` or
    `variation_name`.
    """
    variation_name = kwargs.get("variation_name", None)

    randgen_mapping = kwargs.get("randgen_mapping", None)
    if not self._should_generate(randgen_mapping):
        return self._make_empty_example()

    if variation_name is not None:
        max_nb_possibilities = \
            self.get_max_nb_possibilities(variation_name=variation_name)
    else:
        max_nb_possibilities = self.get_max_nb_possibilities()
    if isinstance(self._cached_examples, list):
        if (
            len(self._cached_examples) > 0
            and uniform(0, 1) <= \
            float(len(self._cached_examples)) / float(max_nb_possibilities)
        ):
            return random_choice(deepcopy(self._cached_examples))
    else:
        pass  # TODO dict case for unit definitions with variations

    if variation_name is not None:
        basic_example = \
            self._generate_random_strategy(variation_name=variation_name)
    else:
        basic_example = self._generate_random_strategy()
    if self._leading_space:
        basic_example.prepend(' ')
    return self._apply_modifiers(basic_example)

def _apply_modifiers(self, example):
    """
    Returns the modified `example`
    after its post-modifiers have been applied.
    """
    if self._modifiers_repr.casegen:
        example = casegen.modify_example(example)
    if self._modifiers_repr.argument_value is not None:
        example = \
            argument.modify_example(
                example, self._modifiers_repr.argument_value
            )
    return example

def __init__(self, identifier, unit_type, leading_space, modifiers):
    self._unit_type = unit_type
    super(UnitReference, self).__init__(
        identifier, leading_space, modifiers
    )
    try:
        self._definition = AST.get_or_create()[unit_type][identifier]
        self._fix_arg_value_modifier()
    except KeyError:
        self._definition = None

def get_template_unit_sym(unit_type):
    """Returns the symbol that corresponds to unit type `unit_type`."""
    if unit_type == UnitType.alias:
        return ALIAS_SYM
    if unit_type == UnitType.slot:
        return SLOT_SYM
    if unit_type == UnitType.intent:
        return INTENT_SYM
    raise TypeError(
        "Tried to get the symbol associated to an invalid unit type: '" + \
        unit_type.__class__.__name__ + "'."
    )

def get_definition(self):
    if self._definition is None:
        try:
            self._definition = \
                AST.get_or_create()[self._unit_type][self._name]
            self._fix_arg_value_modifier()
        except KeyError:
            raise KeyError(
                "Couldn't find the definition corresponding to " + \
                self.full_name + "."
            )
    return self._definition

def _compute_nb_possibilities(self):
    return \
        self.get_definition() \
            .get_max_nb_possibilities(
                variation_name=self._modifiers_repr.variation_name
            )

def _generate_random_strategy(self):
    return \
        self.get_definition() \
            .generate_random(
                variation_name=self._modifiers_repr.variation_name
            )

def _generate_all_strategy(self):
    return \
        self.get_definition() \
            .generate_all(
                variation_name=self._modifiers_repr.variation_name
            )

def _generate_n_strategy(self, n):
    return \
        self.get_definition() \
            .generate_nb_possibilities(
                n, variation_name=self._modifiers_repr.variation_name
            )

def __init__(self, *args, **kwargs):
    super(SlotDefinition, self).__init__(*args, **kwargs)
    self._synonyms = None

def __init__(self, base_filepath=None):
    super(RasaMdAdapter, self).__init__(base_filepath, None)
    self._base_file_contents = None

def __contains__(self, variation_name):
    """
    Returns `True` if `variation_name` is a variation
    that is declared for the current definition.
    """
    return (variation_name in self._variation_rules)

def generate_all(self, variation_name=None):
    """Overriding to prevent caching of examples for just one variation."""
    if not self._variation_rules:
        return super(UnitDefinition, self).generate_all()

    if isinstance(self._cached_examples, list):
        self._cached_examples = dict()
    if variation_name not in self._cached_examples:
        basic_examples = \
            self._generate_all_strategy(variation_name=variation_name)
        if self._leading_space:
            for ex in basic_examples:
                ex.prepend(' ')
        self._cached_examples[variation_name] = \
            self._apply_modifiers_to_all(basic_examples)
    return deepcopy(self._cached_examples[variation_name])

def _generate_all_strategy(self, variation_name=None):
    if variation_name is None:
        relevant_rules = self._all_rules
    elif variation_name in self._variation_rules:
        relevant_rules = self._variation_rules[variation_name]
    else:
        raise SyntaxError(
            "Tried to generate examples for variation '" + \
            str(variation_name) + "' of " + self.full_name + \
            ", but this variation has no rules associated to it."
        )

    generated_examples = []
    for rule in relevant_rules:
        current_examples = rule.generate_all()
        if self.unit_type == UnitType.slot:
            for ex in current_examples:
                ex._slot_value = rule.slot_value
                if (
                    ex._slot_value is not None
                    and ex._slot_value.strip() == SLOT_VAL_FIRST_RULE
                ):
                    if len(rule._contents) == 0:
                        raise SyntaxError(
                            "The slot value given for one of the rules " + \
                            "of " + self.full_name + \
                            " references the first token of an empty rule."
                        )
                    ex._slot_value = rule._contents[0]._name
        for ex in current_examples:
            ex.remove_leading_space()
        generated_examples = \
            extend_no_dup(generated_examples, current_examples)
    return generated_examples

def generate_train(self):
    """
    Returns a list of examples to make up the training set.
    The list has as many examples as were asked in teh templates.
    """
    if self._nb_training_ex_asked is None:
        return self.generate_all()
    if self._nb_training_ex_asked == 0:
        return []
    return self.generate_nb_possibilities(self._nb_training_ex_asked)

def generate_test(self, training_examples):
    """
    Returns a list of examples that can be put in the test set
    (not present in the training set).
    The list has as many examples as were asked in the templates.
    """
    if self._nb_testing_ex_asked is None or self._nb_testing_ex_asked == 0:
        return []
    if (
        self._nb_testing_ex_asked < \
        float(self.get_max_nb_possibilities()) / 5.0
    ):
        test_examples = []
        loop_count = 0
        while len(test_examples) < self._nb_testing_ex_asked:
            loop_count += 1
            current_ex = self.generate_random()
            if current_ex in training_examples:
                continue
            add_example_no_dup(test_examples, current_ex)

            if loop_count > 10*self._nb_testing_ex_asked:
                break
        return test_examples
    else:
        test_examples = []
        all_examples = self.generate_all()
        shuffle(all_examples)
        for ex in all_examples:
            if ex in training_examples:
                continue
            add_example_no_dup(test_examples, ex)

            if len(test_examples) == self._nb_testing_ex_asked:
                break
        return test_examples

def prepare_example(self, example):
    """Transforms an example into a str writable to an output file."""
    raise NotImplementedError()

def prepare_example(self, example):
    return json.dumps(
        cast_to_unicode(example.as_dict()),
        ensure_ascii=False, sort_keys=True
    )

def _write_batch(self, output_file_handle, batch):
    output_file_handle.writelines([
        self.prepare_example(example) + "\n"
        for example in batch.examples
    ])

def _get_base_to_extend(self):
    if self._base_file_contents is None:
        if self._base_filepath is None:
            return self._get_empty_base()
        with io.open(self._base_filepath, 'r') as base_file:
            self._base_file_contents = ''.join(base_file.readlines())
        self.check_base_file_contents()
    return self._base_file_contents

def check_base_file_contents(self):
    if self._base_file_contents is None:
        return
    if not isinstance(self._base_file_contents, string_types):
        raise SyntaxError(
            "Couldn't load valid data from base file '" + \
            self._base_file_contents + "'"
        )

def prepare_example(self, example):
    def entity_to_rasa(entity):
        return {
            "entity": entity.slot_name,
            "value": entity.value,
            "start": entity._start_index,
            "end": entity._start_index + entity._len,
        }

    return {
        "intent": example.intent_name,
        "text": example.text,
        "entities": [entity_to_rasa(entity) for entity in example.entities]
    }

def __format_synonyms(cls, synonyms):
    # {str: [str]} -> [{"value": str, "synonyms": [str]}]
    return [
        {
            "value": slot_name,
            "synonyms": synonyms[slot_name]
        }
        for slot_name in synonyms
        if len(synonyms[slot_name]) > 1
    ]

def entity_to_rasa(entity):
    return {
        "entity": entity.slot_name,
        "value": entity.value,
        "start": entity._start_index,
        "end": entity._start_index + entity._len,
    }

def _get_base_to_extend(self):
    if self._base_file_contents is None:
        if self._base_filepath is None:
            return self._get_empty_base()
        with io.open(self._base_filepath, 'r') as base_file:
            self._base_file_contents = json.load(base_file)
        self.check_base_file_contents()
    return self._base_file_contents

def _get_empty_base(self):
    return {
        "rasa_nlu_data": {
            "common_examples": None,
            "regex_features": [],
            "lookup_tables": [],
            "entity_synonyms": None,
        }
    }

def check_base_file_contents(self):
    """
    Checks that `self._base_file_contents` contains well formatted JSON.
    Throws a `SyntaxError` if the data is incorrect.
    """
    if self._base_file_contents is None:
        return
    if not isinstance(self._base_file_contents, dict):
        self._base_file_contents = None
        raise SyntaxError(
            "Couldn't load valid data from base file '" + \
            self._base_filepath + "'"
        )
    else:
        if "rasa_nlu_data" not in self._base_file_contents:
            self._base_file_contents = None
            raise SyntaxError(
                "Expected 'rasa_nlu_data' as a root of base file '" + \
                self._base_filepath + "'")

def _write_batch(self, output_file_handle, batch):
    output_file_handle.write(
        "<!-- Generated using Chatette v" + cast_to_unicode(__version__) + \
        " -->\n\n"
    )

    prepared_examples = dict()
    for example in batch.examples:
        append_to_list_in_dict(
            prepared_examples,
            example.intent_name, self.prepare_example(example)
        )

    for intent_name in prepared_examples:
        output_file_handle.write(
            "## intent:" + cast_to_unicode(intent_name) + '\n'
        )
        for text in prepared_examples[intent_name]:
            output_file_handle.write(cast_to_unicode("- " + text + '\n'))
        output_file_handle.write(cast_to_unicode('\n'))

    output_file_handle.write(
        cast_to_unicode(self.__format_synonyms(batch.synonyms))
    )

    remainder = self._get_base_to_extend()
    if remainder is not None:
        output_file_handle.write(cast_to_unicode(remainder) + '\n')

def __format_synonyms(cls, synonyms):
    """
    Returns a str that will be written in the output files for all
    the synonyms `synonyms`.
    """
    result = ""
    for syn_name in synonyms:
        if len(synonyms[syn_name]) > 1:
            result += "## synonym:" + syn_name + '\n'
            for syn in synonyms[syn_name]:
                if syn != syn_name:
                    result += "- " + syn + '\n'
            result += '\n'
    return result

def open_new_file(self, filepath):
    """Opens the new (master) file, making the parser ready to parse it."""
    try:
        self.input_file_manager.open_file(filepath)
    except IOError as e:
        raise IOError(
            "There was an error while opening file '" + \
            str(cast_to_unicode(filepath)) + "': " + str(e) + "."
        )
    except FileAlreadyOpened as e:
        err_msg = str(e)
        current_file_name = self.input_file_manager.get_current_file_name()
        if current_file_name is not None:
            err_msg += \
                "\nContinuing the parsing of '" + str(current_file_name) + \
                "'."
        print_warn(err_msg)

def _parse_file_inclusion(self, lexical_tokens):
    """
    Opens the file that is included by the tokenized line `lexical_tokens`.
    @pre: `lexical_tokens` contain a tokenized file inclusion line.
    """
    self.open_new_file(lexical_tokens[1].text)
    print_DBG(
        "Parsing file: " + \
        self.input_file_manager.get_current_file_name()
    )

def get_current_file_name(self):
    if self._current_file is None:
        return None
    return self._current_file.name

def _parse_unit_declaration_line(self, line_tokens):
    """
    Parses the tokens `line_tokens` that correspond to a whole line
    where a unit is declared.
    Adds the definition to the AST.
    """
    if not self._declaration_line_allowed:
        self.input_file_manager.syntax_error(
            "Didn't expect a unit declaration to start here."
        )

    (unit, variation) = self._parse_unit_declaration(line_tokens)

    try:
        self.ast.add_unit(unit)
    except ValueError as e:
        if variation is None:
            self.input_file_manager.syntax_error(str(e))
        elif variation in self.ast[unit.unit_type][unit.identifier]:
            self.input_file_manager.syntax_error(
                "Variation '" + str(variation) + "' was already " + \
                "declared for " + unit.full_name + "."
            )
        else:  # new variation was declared
            pass
    self._current_variation_name = variation
    self._current_unit_declaration = unit

def _parse_unit_declaration(self, lexical_tokens):
    """
    Parses the tokens `lexical_tokens` that contain a unit declaration.
    Returns the corresponding concrete unit.
    """
    if lexical_tokens[0].type == TerminalType.alias_decl_start:
        builder = AliasDefBuilder()
    elif lexical_tokens[0].type == TerminalType.slot_decl_start:
        builder = SlotDefBuilder()
    elif lexical_tokens[0].type == TerminalType.intent_decl_start:
        builder = IntentDefBuilder()
    else:  # Should never happen
        raise ValueError(
            "Tried to parse a line as if it was a unit declaration " + \
            "while it wasn't."
        )

    i = 1
    while i < len(lexical_tokens):
        token = lexical_tokens[i]
        if token.type == TerminalType.unit_identifier:
            builder.identifier = token.text
        elif token.type == TerminalType.casegen_marker:
            builder.casegen = True
        elif token.type == TerminalType.randgen_marker:
            builder.randgen = True
        elif token.type == TerminalType.randgen_name:
            builder.randgen_name = token.text
        elif token.type == TerminalType.variation_marker:
            pass
        elif token.type == TerminalType.variation_name:
            builder.variation = token.text
        elif token.type == TerminalType.arg_marker:
            pass
        elif token.type == TerminalType.arg_name:
            builder.arg_name = token.text
        elif (
            token.type in \
            (TerminalType.alias_decl_end,
             TerminalType.slot_decl_end,
             TerminalType.intent_decl_end)
        ):
            i += 1
            break
        else:
            raise ValueError(  # Should never happen
                "Detected invalid token type in unit definition: " + \
                token.type.name
            )
        i += 1


    if (
        i < len(lexical_tokens)
        and lexical_tokens[i].type == TerminalType.annotation_start
    ):
        if not isinstance(builder, IntentDefBuilder):
            if isinstance(builder, AliasDefBuilder):
                unit_type = "alias"
            else:
                unit_type = "slot"
            print_warn(
                "Found an annotation when parsing " + unit_type + " '" + \
                builder.identifier + "'\n" + \
                "Annotations are currently only supported for intent " + \
                "definitions. Any other annotation is ignored."
            )
        else:
            annotation_tokens = lexical_tokens[i:]
            annotation = self._annotation_tokens_to_dict(annotation_tokens)
            (nb_training_ex, nb_testing_ex) = \
                self._parse_intent_annotation(annotation)
            builder.nb_training_ex = nb_training_ex
            builder.nb_testing_ex = nb_testing_ex

    return (builder.create_concrete(), builder.variation)

def _annotation_tokens_to_dict(self, tokens):
    """
    Transforms the tokens `tokens` that contain an annotation into a dictionary
    that contains the same information.
    @pre: `tokens` really contains an annotation (starting at the beginning of
        the list).
    @raises: - `ValueError` if the precondition is not met.
            - `SyntaxError` if the annotation contains the same key twice.
    """
    if len(tokens) == 0 or tokens[0].type != TerminalType.annotation_start:
        raise ValueError(
            "Tried to parse tokens as if they were an annotation while " + \
            "they weren't"
        )

    result = dict()
    current_key = None
    for token in tokens:
        if token.type == TerminalType.annotation_end:
            break
        elif token.type == TerminalType.key:
            current_key = token.text
        elif token.type == TerminalType.value:
            if current_key in result:
                self.input_file_manager.syntax_error(
                    "Annotation contained the key '" + current_key + \
                    "' twice."
                )
            result[current_key] = token.text

    return result

def _parse_intent_annotation(self, annotation):
    """
    Given a dict representing the annotation corresponding to an intent
    declaration, returns the number of examples asked in the training
    and testing sets (as a 2-tuple).
    Returns `None` instead of a number if a number was not provided.
    @raises - `SyntaxError` if the number of examples provided are
              actually not integral numbers.
            - `SyntaxError` if the annotation contains the same information
              at least twice.
    Prints a warning if the annotation contains unrecognized keys.
    """
    nb_training_ex = None
    nb_testing_ex = None
    for key in annotation:
        if key is None or key.lower() in ("training", "train"):
            if nb_training_ex is not None:
                self.input_file_manager.syntax_error(
                    "Detected a number of examples for training set " + \
                    "several times."
                )
            nb_training_ex = \
                self._str_to_int(
                    annotation[key],
                    "Couldn't parse the annotation of the intent."
                )
        elif key.lower() in ("testing", "test"):
            if nb_testing_ex is not None:
                self.input_file_manager.syntax_error(
                    "Detected a number of examples for testing set " + \
                    "several times."
                )
            nb_testing_ex = \
                self._str_to_int(
                    annotation[key],
                    "Couldn't parse the annotation of the intent."
                )
        else:
            print_warn("Unsupported key in the annotation: '" + key + "'.")
    return (nb_training_ex, nb_testing_ex)

def _str_to_int(self, text, err_msg):
    """
    Transforms the str `text` into an int.
    @raises: `SyntaxError` with the message `err_msg` and a small message
             explaining `text` is not a valid int
             if the cast couldn't be performed.
    """
    try:
        return int(text)
    except ValueError:
        self.input_file_manager.syntax_error(
            err_msg + " '" + text + "' is not a valid integral number."
        )

def _parse_rule(self, tokens):
    """
    Handles the tokens `tokens` that contain a rule (inside a unit
    definition).
    Returns the rule (`Rule`) that `tokens` represent.
    """
    # TODO replace this with a (stateful) iterator to make it more readable
    rule_contents = []
    current_builder = None
    leading_space = False
    slot_value = None
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token.type == TerminalType.whitespace:
            leading_space = True
            if current_builder is not None:
                rule_contents.append(current_builder.create_concrete())
                current_builder = None
        # Units and rule contents
        elif token.type == TerminalType.word:
            rule_contents.append(Word(token.text, leading_space))
            leading_space = False
        elif (
            token.type in \
            (TerminalType.alias_ref_start,
                TerminalType.slot_ref_start,
                TerminalType.intent_ref_end)
        ):
            if current_builder is not None:
                rule_contents.append(current_builder.create_concrete())
            current_builder = UnitRefBuilder()
            current_builder.leading_space = leading_space
            if token.type == TerminalType.alias_ref_start:
                current_builder.type = UnitType.alias
            elif token.type == TerminalType.slot_ref_start:
                current_builder.type = UnitType.slot
            elif token.type == TerminalType.intent_ref_start:
                current_builder.type = UnitType.intent
        elif (
            token.type in \
            (TerminalType.alias_ref_end,
             TerminalType.slot_ref_end,
             TerminalType.intent_ref_end)
        ):
            rule_contents.append(current_builder.create_concrete())
            current_builder = None
            leading_space = False
        elif token.type == TerminalType.unit_identifier:
            current_builder.identifier = token.text
        elif token.type == TerminalType.choice_start:
            if current_builder is not None:
                rule_contents.append(current_builder.create_concrete())
            current_builder = ChoiceBuilder()
            current_builder.leading_space = leading_space
            last_internal_choice_token = \
                find_index_last_choice_content(tokens, i)
            if last_internal_choice_token is not None:
                i += 1
                if tokens[i].type == TerminalType.casegen_marker:
                    current_builder.casegen = True
                    i += 1
                internal_rules = \
                    self._parse_choice(
                        tokens[i:last_internal_choice_token + 1]
                    )
                current_builder.rules = internal_rules
                i = last_internal_choice_token
            else:
                self.input_file_manager.syntax_error(
                    "Inconsistent choice start and ending."
                )
        elif token.type == TerminalType.choice_end:
            rule_contents.append(current_builder.create_concrete())
            current_builder = None
            leading_space = False
        # Modifiers
        elif token.type == TerminalType.casegen_marker:
            current_builder.casegen = True
        elif token.type == TerminalType.randgen_marker:
            current_builder.randgen = True
        elif token.type == TerminalType.opposite_randgen_marker:
            current_builder.randgen_opposite = True
        elif token.type == TerminalType.randgen_name:
            current_builder.randgen_name = token.text
        elif token.type == TerminalType.percentgen_marker:
            pass
        elif token.type == TerminalType.percentgen:
            current_builder.randgen_percent = \
                self._str_to_int(
                    token.text,
                    "Couldn't parse the percentage " + \
                    "for the random generation modifier."
                )
        elif token.type == TerminalType.variation_marker:
            pass
        elif token.type == TerminalType.variation_name:
            current_builder.variation = token.text
        elif token.type == TerminalType.arg_marker:
            pass
        elif token.type == TerminalType.arg_value:
            current_builder.arg_value = token.text
        elif token.type == TerminalType.slot_val_marker:
            pass
        elif token.type == TerminalType.slot_val:
            slot_value = token.text
        else:
            raise ValueError(  # Should never happen
                "Detected invalid token type in rule: " + \
                token.type.name + " for text '" + token.text + "'."
            )
        i += 1
    if current_builder is not None:
        rule_contents.append(current_builder.create_concrete())

    if self._current_unit_declaration is not None:
        return Rule(
            self._current_unit_declaration.full_name,
            rule_contents, slot_value
        )
    # NOTE can only come from an interactive command (the 'rule' command)
    return Rule(None, rule_contents, slot_value)

def _parse_choice(self, tokens):
    rules = []

    current_rule_start_index = 0
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token.type == TerminalType.choice_sep:
            rules.append(
                self._parse_rule(tokens[current_rule_start_index:i])
            )
            current_rule_start_index = i + 1
        if token.type == TerminalType.choice_start:
            end_choice_index = find_matching_choice_end(tokens, i)
            if end_choice_index is None:
                self.input_file_manager.syntax_error(
                    "Inconsistent choice starts and endings."
                )
            i = end_choice_index
        i += 1

    rules.append(
        self._parse_rule(tokens[current_rule_start_index:i])
    )

    return rules

def get_current_line_information(self):
    if self._current_file is None:
        return (None, None, self._last_read_line)
    return (
        self._current_file.name, self._current_file.line_nb,
        self._last_read_line
    )

def readline(self):
    self.line_nb += 1
    return self.f.readline()

def create_concrete(self):
    from chatette.units.modifiable.choice import Choice
    self._check_information()
    return Choice(
        self.leading_space, self._build_modifiers_repr(),
        self.rules
    )

def create_concrete(self):
    from chatette.units.modifiable.unit_reference import UnitReference
    self._check_information()
    return UnitReference(
        self.identifier, self.type,
        self.leading_space, self._build_modifiers_repr()
    )

def create_concrete(self):
    from chatette.units.modifiable.definitions.alias import AliasDefinition
    self._check_information()
    if self.variation is not None:
        definitions = AST.get_or_create()[UnitType.alias]
        if self.identifier in definitions:
            return definitions[self.identifier]
    return AliasDefinition(self.identifier, self._build_modifiers_repr())

def create_concrete(self):
    from chatette.units.modifiable.definitions.slot import SlotDefinition
    self._check_information()
    if self.variation is not None:
        definitions = AST.get_or_create()[UnitType.slot]
        if self.identifier in definitions:
            return definitions[self.identifier]
    return SlotDefinition(self.identifier, self._build_modifiers_repr())

def create_concrete(self):
    from chatette.units.modifiable.definitions.intent import IntentDefinition
    self._check_information()
    if self.variation is not None:
        definitions = AST.get_or_create()[UnitType.intent]
        if self.identifier in definitions:
            return definitions[self.identifier]
    return IntentDefinition(
        self.identifier, self._build_modifiers_repr(),
        self.nb_training_ex, self.nb_testing_ex
    )

def execute(self):
    if len(self.command_tokens) < 5:
        self.print_wrapper.error_log(
            "Missing some arguments\nUsage: " + self.usage_str
        )
        return

    unit_type = CommandStrategy.get_unit_type_from_str(self.command_tokens[1])
    if unit_type is None:
        self.print_wrapper.error_log(
            "Unknown unit type: '" + str(self.command_tokens[1]) + "'."
        )
        return

    unit_regex = self.get_regex_name(self.command_tokens[2])

    modifier_name = self.command_tokens[3]
    # TODO this is not the best way to get the value
    modifier_value = \
        CommandStrategy.split_exact_unit_name(self.command_tokens[4])[0]

    if unit_regex is None:
        try:
            [unit_name, variation_name] = \
                CommandStrategy.split_exact_unit_name(
                    self.command_tokens[2]
                )
        except SyntaxError:
            self.print_wrapper.error_log(
                "Unit identifier couldn't be interpreted. " + \
                "Did you mean to escape some hashtags '#'?"
            )
            return
        if variation_name is not None:
            self.print_wrapper.error_log(
                "Cannot set a modifier for the variation of a unit."
            )
            return
        self._set_modifier(
            unit_type, unit_name, modifier_name, modifier_value
        )
    else:
        count = 0
        for unit_name in self.next_matching_unit_name(
            unit_type, unit_regex
        ):
            self._set_modifier(
                unit_type, unit_name, modifier_name, modifier_value
            )
            count += 1
        if count == 0:
            self.print_wrapper.write("No " + unit_type.name + " matched.")

def _set_modifier(self, unit_type, unit_name, modifier_name, value):
    unit = AST.get_or_create()[unit_type][unit_name]
    modifier_name = modifier_name.lower()
    if modifier_name in ("casegen", CASE_GEN_SYM):
        try:
            value = str_to_bool(value)
            unit.set_casegen(value)
        except ValueError:
            self.print_wrapper.write(
                "Invalid value for case generation modifier " + \
                "(True or False)."
            )
            return
    elif modifier_name in ("arg", ARG_SYM):
        unit.set_arg_value(value)
    elif modifier_name in ("randgen", RAND_GEN_SYM):
        try:
            value = str_to_bool(value)
            unit.set_randgen(value)
        except ValueError:
            self.print_wrapper.write(
                "Invalid value for random generation modifier " + \
                "(True or False)."
            )
            return
    elif modifier_name in "randgen-name":
        unit.set_randgen_name(modifier_name)
    elif modifier_name in ("randgen-percent", RAND_GEN_PERCENT_SYM):
        try:
            value = float(value)
            unit.set_randgen_percent(value)
        except ValueError:
            self.print_wrapper.write(
                "Invalid value for the random generation percentage " + \
                "modifier (expected a float)."
            )
            return
    else:
        self.print_wrapper.write(
            "Invalid modifier selected (can be 'casegen', " + \
            "'randgen', 'randgen-name', 'randgen-percent' or 'arg')."
        )
        return
    self.print_wrapper.write(
        "Modifier for " + unit_type.name + " '" + unit_name + \
        "' successfully changed."
    )

def execute(self):
    """
    Implements the command `unhide` which restores a unit definition that
    was hidden from the AST.
    """
    if len(self.command_tokens) < 3:
        self.print_wrapper.error_log(
            "Missing some arguments\nUsage: " +
            'unhide <unit-type> "<unit-name>"'
        )
        return

    unit_type = CommandStrategy.get_unit_type_from_str(self.command_tokens[1])
    if unit_type is None:
        self.print_wrapper.error_log(
            "Unknown unit type: '" + str(self.command_tokens[1]) + "'."
        )
        return

    unit_regex = self.get_regex_name(self.command_tokens[2])
    if unit_regex is None:
        try:
            [unit_name, variation_name] = \
                CommandStrategy.split_exact_unit_name(self.command_tokens[2])
        except SyntaxError:
            self.print_wrapper.error_log(
                "Unit identifier couldn't be interpreted. " + \
                "Did you mean to escape some hashtags '#'?"
            )
            return
        self.execute_on_unit(unit_type, unit_name, variation_name)
    else:
        unit_names = [
            unit_name
            for unit_name in HideCommand.stored_units[unit_type.name]
            if unit_regex.match(unit_name)
        ]
        if len(unit_names) == 0:
            self.print_wrapper.write("No " + unit_type.name + " matched.")

        for unit_name in unit_names:
            self.execute_on_unit(unit_type, unit_name)

def execute_on_unit(self, unit_type, unit_name, variation_name=None):
    if variation_name is None:
        try:
            unit = HideCommand.stored_units[unit_type.name][unit_name]
            AST.get_or_create().add_unit(unit, unit_type)
            del HideCommand.stored_units[unit_type.name][unit_name]
            self.print_wrapper.write(
                unit_type.name.capitalize() + " '" + unit_name + \
                "' was successfully restored."
            )
        except KeyError:
            self.print_wrapper.error_log(
                unit_type.name.capitalize() + " '" + unit_name + \
                "' was not previously hidden."
            )
        except ValueError:
            self.print_wrapper.error_log(
                unit_type.name.capitalize() + " '" + unit_name + \
                "' is already defined in the parser."
            )
    else:
        try:
            unit = AST.get_or_create()[unit_type][unit_name]
        except KeyError:
            self.print_wrapper.error_log(
                unit_type.name.capitalize() + " '" + unit_name + \
                "' is not defined."
            )
            return
        try:
            rules = \
                HideCommand.stored_variations[unit_type.name][unit_name][variation_name]
            if variation_name in unit._variation_rules:
                self.print_wrapper.error_log(
                    "Variation '" + variation_name + \
                    "' is already defined for " + unit_type.name + \
                    " '" + unit_name + "'."
                )
                return
            unit.add_all_rules(rules, variation_name)
            self.print_wrapper.write(
                "Variation '" + variation_name + "' of " + \
                unit_type.name + " '" + unit_name + \
                "' was successfully restored."
            )
        except KeyError:
            self.print_wrapper.error_log(
                "Variation '" + variation_name + \
                "' of " + unit_type.name + " '" + unit_name + \
                "' was not previously hidden."
            )

def split_exact_unit_name(text):
    """
    Removes the double quotes at the beginning and end of `text` and
    splits `text` into a unit name and a variation identifier.
    Those two parts are separated in `text` by a hashtag `#` (unescaped).
    Returns a list with both those str inside it or the unit name and
    `None` for the variation identifier if it wasn't found.
    @raises: - `SyntaxError` if `text` is not valid (several hashtags),
    """
    no_quote_text = text[1:-1].replace(ESCAPEMENT_SYM + '"', '"')
    splitted = no_quote_text.split(VARIATION_SYM)
    processed_splitted = []
    current_word = ""
    for word in splitted:
        if word.endswith(ESCAPEMENT_SYM):
            if current_word == "":
                current_word = word[:-1]
            else:
                current_word += VARIATION_SYM + word[:-1]
        elif current_word == "":
            processed_splitted.append(word)
        else:
            processed_splitted.append(current_word + VARIATION_SYM + word)
            current_word = ""
    if len(processed_splitted) > 2:
        raise SyntaxError("Too many hashtags in unit identifier.")
    if len(processed_splitted) == 1:
        return [processed_splitted[0], None]
    return processed_splitted

def get_regex_name(self, name):
    """
    If a regex is used within `name`,
    returns a compiled regex that is able to find all units with a name
    that matches some pattern.
    Returns `None` otherwise.
    """
    if (
        name.startswith(REGEX_SYM)
        and (
            name.endswith(REGEX_SYM)
            or name[-2] == REGEX_SYM
            or name[-3] == REGEX_SYM)
    ):
        splitted_str = [e for e in name.split(REGEX_SYM) if e != ""]
        if len(splitted_str) == 1:
            return re.compile(name[1:-1].replace('\\'+REGEX_SYM, REGEX_SYM))

        flags = splitted_str[-1]
        text_without_flags = rchop(name, flags)
        self._is_regex_global = 'g' in flags
        if 'i' in flags:
            return re.compile(
                text_without_flags[1:-1].replace(
                    '\\'+REGEX_SYM, REGEX_SYM
                ),
                re.IGNORECASE
            )
        return re.compile(
            text_without_flags[1:-1].replace('\\'+REGEX_SYM, REGEX_SYM)
        )
    return None

def next_matching_unit_name(self, unit_type, regex):
    """
    Yields the next unit name of type `unit_type`
    whose name matches `regex`.
    """
    relevant_dict = AST.get_or_create()._get_relevant_dict(unit_type)
    if self._is_regex_global:
        for unit_name in relevant_dict:
            if regex.search(unit_name):
                yield unit_name
    else:
        for unit_name in relevant_dict:
            if regex.match(unit_name):
                yield unit_name

def execute(self):
    """
    Executes the whole command represented by this object.
    This method can be overriden by subclasses if a different algorithm is
    required.
    """
    # TODO support variations
    if len(self.command_tokens) < 3:
        self.print_wrapper.error_log(
            "Missing some arguments\nUsage: " + self.usage_str
        )
        return

    unit_type = CommandStrategy.get_unit_type_from_str(self.command_tokens[1])
    if unit_type is None:
        self.print_wrapper.error_log(
            "Unknown unit type: '" + str(self.command_tokens[1]) + "'."
        )
        return

    unit_regex = self.get_regex_name(self.command_tokens[2])
    if unit_regex is None:
        try:
            [unit_name, variation_name] = \
                CommandStrategy.split_exact_unit_name(
                    self.command_tokens[2]
                )
        except SyntaxError:
            self.print_wrapper.error_log(
                "Unit identifier couldn't be interpreted. " + \
                "Did you mean to escape some hashtags '#'?")
            return
        self.execute_on_unit(unit_type, unit_name, variation_name)
    else:
        count = 0
        for unit_name in self.next_matching_unit_name(
            unit_type, unit_regex
        ):
            self.execute_on_unit(unit_type, unit_name)
            count += 1
        if count == 0:
            self.print_wrapper.write("No " + unit_type.name + " matched.")
    self.finish_execution()

def execute_on_unit(self, unit_type, unit_name, variation_name=None):
    try:
        unit = AST.get_or_create()[unit_type][unit_name]
        self.print_wrapper.write(unit.short_description())
        if variation_name is not None:
            if variation_name in unit._variation_rules:
                self.print_wrapper.write(
                    "Variation '" + variation_name + \
                    "' is defined for this " + unit.unit_type.name + "."
                )
            else:
                self.print_wrapper.write(
                    "Variation '" + variation_name + \
                    "' is not defined for this " + unit.unit_type.name + "."
                )
    except KeyError:
        self.print_wrapper.write(
            unit_type.name.capitalize() + " '" + unit_name + \
            "' is not defined."
        )
    self.print_wrapper.write("")

def execute_on_unit(self, unit_type, unit_name, variation_name=None):
    try:
        unit = AST.get_or_create()[unit_type][unit_name]
        self.print_wrapper.write(unit.short_description())

        if variation_name is None:
            self.print_wrapper.write(
                "Template rules:\n" + str(unit.as_template_str())
            )
        else:  # TODO
            pass
    except KeyError:
        self.print_wrapper.write(
            unit_type.name.capitalize() + " '" + unit_name + \
            "' is not defined."
        )

def execute(self):
    """
    Implements the command `execute` which executes each line of a file
    as if they were commands (unless they start with a double slash `//`).
    """
    if len(self.command_tokens) < 2:
        self.print_wrapper.error_log(
            "Missing some arguments\nUsage: " + self.usage_str
        )
        return

    # TODO there may be a better way to get the file name
    with io.open(self.split_exact_unit_name(self.command_tokens[1])[0], 'r') as command_file:
        commands = [
            line.rstrip()
            for line in command_file.readlines()
            if not line.lstrip().startswith("//")
        ]
    redirection_tuple = self.print_wrapper.get_redirection()
    if redirection_tuple is not None:
        (_, redirection_filepath) = redirection_tuple
        if redirection_filepath is not None:
            text_to_append = \
                ' ' + REDIRECTION_APPEND_SYM + ' ' + redirection_filepath
            for (i, cmd) in enumerate(commands):
                if (
                    REDIRECTION_APPEND_SYM not in cmd
                    and REDIRECTION_SYM not in cmd
                ):
                    commands[i] += text_to_append
    return commands

def execute(self):
    """Implements the command `stats`, printing parsing statistics."""
    self.print_wrapper.write(str(Stats.get_or_create()))

def tokenize(command_str):
    """Tokenizes a string that is a command."""
    splitted = command_str.split()
    if len(splitted) == 0:
        return []
    if len(splitted) == 1:
        return [splitted[0]]
    tokens = []
    current_token = ""
    inside_token = False
    inside_regex = False
    for word in splitted:
        if inside_token:
            current_token += ' ' + word
            if word.endswith('"') and (len(word) < 2 or word[-2] != '\\'):
                inside_token = False
                tokens.append(current_token.rstrip())
                current_token = ""
        elif inside_regex:
            current_token += ' ' + word
            if CommandStrategy._is_end_regex(word):
                inside_regex = False
                tokens.append(current_token)
                current_token = ""
        elif (
            word.startswith('"') and word.endswith('"')
            and (len(word) < 2 or word[-2] != '\\')
        ):
            tokens.append(word)
        elif word.startswith('"'):
            inside_token = True
            current_token += word
        elif word.startswith("/") and CommandStrategy._is_end_regex(word):
            tokens.append(word)
        elif word.startswith("/"):
            inside_regex = True
            current_token += word
        else:  # not inside a token and not starting with "
            tokens.append(word)
    if current_token != "":
        tokens.append(current_token.rstrip())
    return tokens

def find_redirection_file_path(tokens):
    """
    Finds the path of the file
    which the output of a command should be redirected to and
    returns it along with the type of redirection that it is (in a 2-tuple).
    The type of redirection is an enumeration item of type
    `RedirectionType`.
    Returns `None` if no redirection was found.
    Returns `(RedirectionType.quiet, None)` if a redirection should be done
    to nowhere.
    (This can be achieved by using the redirections symbols and providing
    no filepath).
    """
    if len(tokens) < 2:
        return None
    if tokens[-2] == REDIRECTION_APPEND_SYM:
        return (RedirectionType.append, tokens[-1])
    if tokens[-2] == REDIRECTION_SYM:
        return (RedirectionType.truncate, tokens[-1])
    if (
        tokens[-1] == REDIRECTION_APPEND_SYM
        or tokens[-1] == REDIRECTION_SYM
    ):
        return (RedirectionType.quiet, None)
    return None

def remove_redirection_tokens(self):
    """
    Removes the tokens that represent a redirection
    from `self.command_tokens`.
    @pre: There are redirection tokens in the tokens.
    """
    if (
        self.command_tokens[-2] == REDIRECTION_APPEND_SYM
        or self.command_tokens[-2] == REDIRECTION_SYM
    ):
        self.command_tokens = self.command_tokens[:-2]
    else:
        self.command_tokens = self.command_tokens[:-1]

def remove_quotes(text):
    """
    Removes the double quotes at the beginning and end of `text` and
    returns it. Double quotes that shouldn't be considered are escaped.
    """
    return text[1:-1].replace(ESCAPEMENT_SYM + '"', '"')

def execute(self):
    """
    Implements the command `rename` which renames a unit
    into something else. Displays an error if the unit wasn't found.
    """
    from chatette.cli.interactive_commands.command_strategy import CommandStrategy
    from chatette.units.ast import AST
    if len(self.command_tokens) < 4:
        self.print_wrapper.error_log(
            "Missing some arguments\nUsage: " + \
            'rename <unit-type> "<old-name>" ' + '"<new-name>"')
        return
    unit_type = \
        CommandStrategy.get_unit_type_from_str(self.command_tokens[1])

    if unit_type is None:
        self.print_wrapper.error_log(
            "Unknown unit type: '" + str(self.command_tokens[1]) + "'."
        )
    else:
        old_name = CommandStrategy.remove_quotes(self.command_tokens[2])
        new_name = CommandStrategy.remove_quotes(self.command_tokens[3])
        if new_name == "":
            self.print_wrapper.error_log(
                "An empty name is not a valid " + unit_type.name + " name."
            )
            return

        try:
            AST.get_or_create().rename_unit(unit_type, old_name, new_name)
            self.print_wrapper.write(
                unit_type.name.capitalize() + " '" + old_name + \
                "' was successfully renamed to '" + new_name + "'.")
        except KeyError:
            self.print_wrapper.error_log(
                "Couldn't find a unit named '" + str(old_name) + "'."
            )
        except ValueError:
            self.print_wrapper.error_log(
                unit_type.name.capitalize() + " '" + new_name + \
                "' is already in use."
            )

def execute(self):
    """
    Implements the command `rule` which generates a certain number of
    examples according to a provided rule.
    """
    if len(self.command_tokens) < 2:
        self.print_wrapper.error_log("Missing some arguments\nUsage: " +
                                     'rule "<rule>" [<number-of-examples]')
        return

    rule_str = CommandStrategy.remove_quotes(self.command_tokens[1])
    nb_examples = None
    if len(self.command_tokens) >= 3:
        try:
            nb_examples = int(self.command_tokens[2])
        except ValueError:
            self.print_wrapper.error_log(
                "The number of examples asked (" + \
                self.command_tokens[2] + ") is a valid integer."
            )

    parser = Parser(None)
    rule_tokens = parser.lexer.lex("\t" + rule_str)
    # pylint: disable=protected-access
    rule = parser._parse_rule(rule_tokens[1:])

    if nb_examples is None:
        examples = rule.generate_all()
    else:
        examples = rule.generate_nb_possibilities(nb_examples)
    self.print_wrapper.write("Generated examples:")
    for ex in examples:
        self.print_wrapper.write(str(ex))

def _compute_full_name(self):
    if self.parent_name is not None:
        return "rule contained in " + self.parent_name
    return "rule not contained in anything"

def execute(self):
    # TODO support variations
    if len(self.command_tokens) < 4:
        self.print_wrapper.error_log(
            "Missing some arguments\nUsage: " + self.usage_str)
        return

    unit_type = \
        CommandStrategy.get_unit_type_from_str(self.command_tokens[1])
    if unit_type is None:
        self.print_wrapper.error_log(
            "Unknown unit type: '" + str(self.command_tokens[1]) + "'."
        )
        return

    unit_regex = self.get_regex_name(self.command_tokens[2])
    rule_str = CommandStrategy.remove_quotes(self.command_tokens[3])
    if unit_regex is None:
        try:
            [unit_name, variation_name] = \
                CommandStrategy.split_exact_unit_name(
                    self.command_tokens[2]
                )
        except SyntaxError:
            self.print_wrapper.error_log(
                "Unit identifier couldn't be interpreted. " + \
                "Did you mean to escape some hashtags '#'?"
            )
            return
        self._add_rule(unit_type, unit_name, variation_name, rule_str)
    else:
        count = 0
        for unit_name in self.next_matching_unit_name(
            unit_type, unit_regex
        ):
            self._add_rule(unit_type, unit_name, None, rule_str)
            count += 1
        if count == 0:
            self.print_wrapper.write("No " + unit_type.name + " matched.")

def __str__(self):
    result = self.full_name + ": "
    if len(self._contents) == 0:
        result += "no contents"
    else:
        for content in self._contents:
            result += str(content) + ", "
    return '<' + result + '>'

def as_template_str(self):
    result = ""
    for content in self._contents:
        result += content.as_template_str()
    if self.slot_value is not None:
        result += ' ' + SLOT_VAL_SYM + ' ' + self.slot_value
    return result

def print_error(self):
    """
    If the corresponding rule didn't match,
    prints the relevant error so the user is aware of what the lexing
    problem was.
    """
    if self._matched is None:
        raise ValueError(
            "Tried to print an error for rule '" + self.__class__.__name__ + \
            "' before it was applied."
        )
    if self._matched:
        raise ValueError(
            "Tried to print an error for rule '" + self.__class__.__name__ + \
            "' when no error occurred."
        )
    if self.error_msg is None:
        raise ValueError(
            "No error to print for rule '" + self.__class__.__name__ + \
            "'."
        )
    InputFileManager.get_or_create() \
        .syntax_error(self.error_msg, self._furthest_matched_index + 1)

def _apply_strategy(self, **kwargs):
    if self._match_one_of(
        [RuleWord, RuleChoice, RuleUnitRef, RuleArgAssignment],
        self._next_index,
        **kwargs
    ):
        if not self._try_to_match_rule(RuleWhitespaces):
            self.error_msg = None
        return True

    return False

def _compute_nb_possibilities(self):
    if len(self._contents) == 0:
        return 1
    acc = None
    for content in self._contents:
        if acc is None:
            acc = content.get_max_nb_possibilities()
        else:
            acc *= content.get_max_nb_possibilities()
    return acc

def _generate_random_strategy(self):
    generated_example = Example()
    randgen_mapping = dict()
    for content in self._contents:
        generated_example.append(
            content.generate_random(randgen_mapping=randgen_mapping)
        )
    return generated_example

def _generate_all_strategy(self):
    if len(self._contents) == 0:
        return []
    generated_examples = None
    for content in self._contents:
        tmp_buffer = []
        content_examples = content.generate_all()
        if generated_examples is None:
            generated_examples = content_examples
        else:
            for ex in generated_examples:
                for content_ex in content_examples:
                    if can_concat_examples(ex, content_ex):
                        new_example = \
                            concat_examples_with_randgen(ex, content_ex)
                        add_example_no_dup(tmp_buffer, new_example)
            generated_examples = tmp_buffer
    if generated_examples is None:
        return []
    return sort_by_texts(generated_examples)

def _apply_strategy(self, **kwargs):
    if not self._try_to_match_rule(RuleUnitDecl):
        return False

    annotation_rule = RuleAnnotation(self._text, self._next_index)
    if annotation_rule.matches():
        self._next_index = annotation_rule.get_next_index_to_match()
        self._update_furthest_matched_index()
        self._tokens.extend(annotation_rule.get_lexical_tokens())
    return True

def _apply_strategy(self, **kwargs):
    """
    `kwargs` can contain a boolean with key `parsing_slot_def` that is
    `True` if the current text is part of a slot definition.
    If this boolean is not in `kwargs`, defaults to `False`.
    """
    parsing_slot_def = kwargs.get("parsing_slot_def", False)

    if not self._try_to_match_rule(
        RuleWhitespaces, parsing_indentation=True
    ):
        self.error_msg = \
            "Invalid token. Expected indentation within unit definitions."
        return False

    while True:
        if self._next_index == len(self._text):
            return True
        content_rule = RuleContentRule(self._text, self._next_index)
        if content_rule.matches(**kwargs):
            self._tokens.extend(content_rule.get_lexical_tokens())
            self._next_index = content_rule.get_next_index_to_match()
            self._update_furthest_matched_index(content_rule)
        else:
            self._update_furthest_matched_index(content_rule)
            self.error_msg = content_rule.error_msg
            break

    if parsing_slot_def:
        old_error_msg = self.error_msg
        if not self._try_to_match_rule(RuleSlotVal, **kwargs):
            self.error_msg = old_error_msg

    if self._next_index < len(self._text):
        old_error_msg = self.error_msg
        if (
            not self._try_to_match_rule(RuleComment) and old_error_msg is not None
        ):
            self.error_msg = old_error_msg

    if self._next_index < len(self._text):
        return False
    return True

def matches(self, **kwargs):
    """
    Applies the rule to `self._text`
    and returns `True` if the rule could be applied successfully.
    `kwargs` will be passed to the subsequent call to `self._apply_strategy`.
    @post: `self.get_lexical_tokens()` will return valid tokens
           iff this method returned `True`.
    """
    if self._matched is None:
        if self._start_index >= len(self._text):
            if self.__class__._empty_match_allowed:
                self._matched = True
            else:
                self._matched = False
                self.error_msg = \
                    "Matching of rule '" + self.__class__.__name__ + "' " + \
                    "failed. Didn't expect an end of line there."
        else:
            self._matched = self._apply_strategy(**kwargs)
    return self._matched

def _apply_strategy(self, **kwargs):
    if not self._try_to_match_rule(RuleUnitStart):
        return False

    if self._text.startswith(CASE_GEN_SYM, self._next_index):
        self._next_index += 1
        self._update_furthest_matched_index()
        self._tokens.append(
            LexicalToken(TerminalType.casegen_marker, CASE_GEN_SYM)
        )

    identifier = extract_identifier(self._text, self._next_index)
    if identifier is not None:
        self._next_index += len(identifier)
        self._update_furthest_matched_index()
        self._tokens.append(
            LexicalToken(TerminalType.unit_identifier, identifier)
        )

    if not self._match_any_order([None, RuleArgDecl, RuleVariation]):
        return False

    if not self._text.startswith(UNIT_END_SYM, self._next_index):
        self.error_msg = \
            "Invalid token. Expected the end of the unit declaration " + \
            "there (using symbol '" + UNIT_END_SYM + "')."
        return False

    # TODO maybe making a function for this would be useful
    if self._tokens[0].type == TerminalType.alias_decl_start:
        unit_end_type = TerminalType.alias_decl_end
    elif self._tokens[0].type == TerminalType.slot_decl_start:
        unit_end_type = TerminalType.slot_decl_end
    elif self._tokens[0].type == TerminalType.intent_decl_start:
        unit_end_type = TerminalType.intent_decl_end
    else:  # Should never happen
        raise ValueError(
            "An unexpected error happened during parsing: tried to " + \
            "parse the end of a unit but couldn't find its start in " + \
            "the previously parsed data.\nData was: " + str(self._tokens)
        )

    self._next_index += 1
    self._update_furthest_matched_index()
    self._tokens.append(LexicalToken(unit_end_type, UNIT_END_SYM))

    return True

def _ensure_python_version_is_supported():
    if not _is_supported_python_version():
        print(
            "[ERROR] Python v" + _get_python_version_as_str() + \
            " is not supported by Chatette. " + \
            "Please use a version of Python older than v2.7.\n"
        )
        raise PreconditionsUnmet()

def _check_python_version():
    if _is_deprecated_python_version():
        print_warn(
            "Python v" + _get_python_version_as_str() + \
            " will not be supported in the future. " + \
            "Please upgrade Python whenever possible."
        )

def _is_supported_python_version():
    return version_info[0] == 3 \
        or version_info[0] == 2 and version_info[1] == 7

def _is_deprecated_python_version():
    return version_info[0] == 2 \
        or version_info[0] == 3 and version_info[1] < 4
